package cn.zhuatech.mdm.deep;import cn.zhuatech.mdm.common.ApiResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/mdm-ops") @PreAuthorize("hasRole('ADMIN')") public class DeepMasterDataAdminController{private final DeepMasterDataService s;public DeepMasterDataAdminController(DeepMasterDataService x){s=x;}@PostMapping("/domains")ApiResponse<?> domain(@RequestBody DeepMasterDataService.DomainInput x){return ApiResponse.ok(s.createDomain(x));}@PostMapping("/domains/{id}/activate")ApiResponse<?> activate(@PathVariable Long id){return ApiResponse.ok(s.activate(id));}@PostMapping("/records/{id}/steward")ApiResponse<?> steward(@PathVariable Long id,@RequestBody DeepMasterDataService.StewardDecision x){return ApiResponse.ok(s.steward(id,x));}@PostMapping("/changes/{id}/approve")ApiResponse<?> approve(@PathVariable Long id,@RequestBody DeepMasterDataService.ApprovalInput x){return ApiResponse.ok(s.approveChange(id,x));}@PostMapping("/outbox/{id}/send")ApiResponse<?> send(@PathVariable Long id){return ApiResponse.ok(s.send(id));}}
